/**
 * Frozen contract for the rebuilt reports layer (`convex/reports/`).
 *
 * Both the Convex backend and the React frontend import metric names, statuses,
 * and result shapes from this module ONLY. Divergence between what the backend
 * materializes and what the UI reads is a compile error, not a blank dashboard.
 *
 * Design: docs/solutions/architecture/athena-reporting-read-optimized-redesign-2026-07-28.md
 * Plan:   docs/solutions/architecture/athena-reporting-read-optimized-implementation-plan-2026-07-28.md
 *
 * FROZEN after Wave 0. Slices escalate contract changes; they do not edit this file.
 */

/**
 * Semantic version of what `foldDay` computes from a day's facts.
 *
 * Version 2 normalizes each fact's currency code before comparing it against
 * the day's currency, so a day whose facts spell the same currency differently
 * (e.g. `ghs` vs `GHS`) is no longer flagged `mixedCurrency`. That flag feeds
 * weekly `completeness`, and an incorrect one makes the weekly surface withhold
 * every total — the reason the bump is not cosmetic.
 *
 * A bump refolds NOTHING on its own. `reportDay` rows keep whatever
 * `foldVersion` they were written with, and no read path compares the two.
 * To make a bump take effect on already-folded days, run
 * `reports/foldVersionRepair.markStaleFoldVersionDays` per store: it marks the
 * stale rows `fold_version_bump` dirty and the sweeper — the single fold
 * authority — refolds them. `countStaleFoldVersionDays` reports whether a
 * store still needs the repair.
 *
 * Version 3 certifies fold provenance: every fold stamps the same
 * `certifiedFoldRevision` on the written `reportDay` AND every `reportSkuDay`
 * row it replaces (see `foldAndReplaceDay` in convex/reports/sweeper.ts). The
 * bump exists so the per-store repair sees every pre-revision day as stale —
 * clean days never refold on their own, so without it existing history would
 * stay uncertified forever.
 */
export const REPORTS_FOLD_VERSION = 3 as const;
/**
 * Version 2 adds the source-derived allocation dimensions carried by payment
 * facts. Replays hash with the version already stored on a fact.
 */
export const REPORTS_FINGERPRINT_VERSION = 2 as const;

