/** One fact as emitted by a domain mutation. Identity is structural. */
export type NewReportFact = {
  sourceDomain: ReportSourceDomain;
  sourceId: string;
  /** Line discriminator within the source document; "" for header-level facts. */
  lineId: string;
  factKind: ReportFactKind;
  /** Business time — when the event happened (NOT sync/arrival time). */
  occurredAt: number;
  /**
   * Normally omitted — ingestion stamps arrival time itself. The reseed
   * walker passes business time here so re-derived historical facts don't
   * postdate their day's close and wrongly fold every reseeded day as
   * `amended`. Live emitters must NOT set this.
   */
  recordedAt?: number;
  currency: string;
  grossAmountMinor: number;
  netAmountMinor: number;
  taxAmountMinor: number;
  discountAmountMinor: number;
  quantity: number;
  productSkuId?: string;
  unitCostMinor?: number;
  /** Source-proven signed allocation; omitted on legacy payment facts. */
  paymentAllocationMinor?: number;
  paymentAllocationCoverage?: "known" | "unknown";
};

